 3→import type {
 4→  StateChange,
 5→  DecisionOpened,
 6→} from "./generated/state-changes.types";
 7→
 8→type StoreInstance = InstanceType<typeof ExerciseStore>;
 9→
10→/** Convert a decision_opened state change to an ActiveDecision for the store. */
11→export function toActiveDecision(c: DecisionOpened): ActiveDecision {
12→  return {
13→    id: c.id,
14→    event_id: c.event_id,
15→    issue_id: c.issue_id,
16→    title: c.title,
17→    description: c.description,
18→    question_type: c.question_type,
19→    options: c.options,
20→    completion_mode: c.completion_mode,
21→    target_roles: c.target_roles,
22→    timeout_ms: c.timeout_ms,
23→    max_selections: c.max_selections,
24→    status: "open",
25→    opened_at_pt_ms: c.opened_at_pt_ms,
26→    closed_at_pt_ms: null,
27→    recommendations: c.recommendations ?? {},
28→  };
29→}
30→
31→/** Apply a single state change to the exercise store. */
32→export function handleStateChange(
33→  change: StateChange,
34→  store: StoreInstance,
35→): void {
36→  switch (change.type) {
37→    case "phase_change":
38→      store.applyPhaseChange(change.phase);
39→      store.applyTimeUpdate(change.time);
40→      break;
41→    case "event_change":
42→      store.updateEvent(change.event_id, change.lifecycle);
43→      break;
44→    case "issue_change":
45→      store.updateIssue(change.issue_id, change.lifecycle, change.released);
46→      break;
47→    case "decision_opened":
48→      store.applyDecisions([
49→        ...store.openDecisions(),
50→        toActiveDecision(change),
51→      ]);
52→      break;
53→    case "decision_closed":
54→      store.closeDecision(change.decision_id);
55→      break;
56→    case "score_change":
57→      store.applyScoreChange(change);
58→      break;
59→    case "recommendation_submitted":
60→      store.applyRecommendation(
61→        change.decision_id,
62→        change.participant_id,
63→        change.option_id,
64→      );
65→      break;
66→    case "speed_change":
67→      store.setSpeedFactor(change.factor);
68→      break;
69→    case "forced_card_applied":
70→      // No UI action needed — forced cards are reflected in the decision's options
71→      break;
72→    case "system_state_change":
73→      store.applySystemChange(change);
74→      break;
75→  }
76→}
