  1→/**
  2→ * Property-style Playwright tests for 2-player mode.
  3→ *
  4→ * Tests the waiting room toggle + role selector, and the player view
  5→ * behaviour when the all_advisors synthetic role is active.
  6→ *
  7→ * Invariants verified:
  8→ * - 2 Players button visible only in simple_collaborative
  9→ * - Clicking 2 Players button shows role selectors with Decision Maker / All Advisors
 10→ * - Start disabled until exactly 2 participants with one of each role
 11→ * - All-advisors player sees tabbed all-advisors-panel, NOT advisor panel
 12→ * - All-advisors player sees all open decisions (bypasses target_roles)
 13→ * - Decision-maker sees composite-key advisor bubbles with role labels
 14→ * - Footer text matches synthetic role
 15→ */
 16→import { test, expect, mockParticipant } from "../fixtures/base.fixture";
 17→import type { Page } from "@playwright/test";
 18→
 19→const EX_ID = 1100;
 20→
 21→const SCENARIO_ROLES = [
 22→  {
 23→    id: "co",
 24→    label: "Commanding Officer",
 25→    player_type: "decision_maker" as const,
 26→  },
 27→  { id: "nav", label: "Navigator", player_type: "advisor" as const },
 28→  { id: "ops", label: "Operations", player_type: "advisor" as const },
 29→  { id: "cyops", label: "CyOps", player_type: "advisor" as const },
 30→];
 31→
 32→function seedScenarioWithRoles(
 33→  mockApi: import("../fixtures/base.fixture").MockApi,
 34→  gameMode: string,
 35→): void {
 36→  if (!mockApi.exerciseMap.has(EX_ID)) {
 37→    mockApi.seedExercise(EX_ID, gameMode, EX_ID);
 38→  }
 39→  if (!mockApi.scenarios.find((s) => s.id === EX_ID)) {
 40→    mockApi.seedScenario({
 41→      id: EX_ID,
 42→      title: "Test Scenario",
 43→      description: "",
 44→      domain_id: null,
 45→      content: { roles: SCENARIO_ROLES, game_mode: gameMode },
 46→      version: 1,
 47→      created_at: new Date().toISOString(),
 48→      updated_at: new Date().toISOString(),
 49→    });
 50→  }
 51→}
 52→
 53→// ── State building blocks ─────────────────────────────────────────────
 54→
 55→const TIME = {
 56→  play_time_ms: 120_000,
 57→  real_time_ms: 120_000,
 58→  factor: 1,
 59→  paused: false,
 60→};
 61→
 62→const SCORE = {
 63→  total_score: 10.0,
 64→  stress: 0,
 65→  turn_number: 2,
 66→  next_decision_time_ms: 180_000,
 67→};
 68→
 69→const CONTEXT = {
 70→  title: "Silent Wake",
 71→  description: "Naval cyber exercise",
 72→  briefing: "You are aboard the USS Sentinel.",
 73→  objectives: ["Defend the ship"],
 74→  rules: ["Time is critical"],
 75→  roles: SCENARIO_ROLES,
 76→};
 77→
 78→const DECISION_OPEN = {
 79→  id: "dec1",
 80→  event_id: "e1",
 81→  issue_id: "iss1",
 82→  title: "Evasive Action",
 83→  description: "Choose a maneuver.",
 84→  question_type: "single_choice",
 85→  options: [
 86→    { id: "opt-a", label: "Hard starboard", score: 10 },
 87→    { id: "opt-b", label: "All stop", score: 5 },
 88→    { id: "opt-c", label: "Maintain course", score: -2 },
 89→  ],
 90→  completion_mode: "first_response",
 91→  target_roles: [] as string[],
 92→  timeout_ms: 300_000,
 93→  status: "open",
 94→  opened_at_pt_ms: 60_000,
 95→  closed_at_pt_ms: null,
 96→  recommendations: {},
 97→};
 98→
 99→const DECISION_TARGETED_CO = {
100→  ...DECISION_OPEN,
101→  id: "dec-co",
102→  title: "CO Only Decision",
103→  target_roles: ["co"],
104→};
105→
106→const DECISION_WITH_COMPOSITE_RECS = {
107→  ...DECISION_OPEN,
108→  id: "dec-recs",
109→  title: "Decision With Role Recs",
110→  recommendations: {
111→    "all-adv-01:nav": "opt-a",
112→    "all-adv-01:ops": "opt-b",
113→    "all-adv-01:cyops": "opt-c",
114→  },
115→};
116→
117→// ── Helpers ───────────────────────────────────────────────────────────
118→
119→interface SnapshotOpts {
120→  phase?: string;
121→  decisions?: (typeof DECISION_OPEN)[];
122→  score?: typeof SCORE | null;
123→}
124→
125→function snapshot(opts: SnapshotOpts = {}) {
126→  return {
127→    exercise_id: EX_ID,
128→    title: "Test Exercise",
129→    phase: opts.phase ?? "running",
130→    time: TIME,
131→    events: [],
132→    issues: [],
133→    decisions: opts.decisions ?? [],
134→    score: opts.score ?? null,
135→  };
136→}
137→
138→function playerUrl(participantId: string, role: string): string {
139→  return `/player?exerciseId=${EX_ID}&participantId=${participantId}&role=${role}`;
140→}
141→
142→async function installPlayerMocks(
143→  page: Page,
144→  snap: ReturnType<typeof snapshot>,
145→  ctx = CONTEXT,
146→): Promise<void> {
147→  const decisions = snap.decisions ?? [];
148→  await page.route(`**/api/exercises/${EX_ID}/engine/snapshot`, (route) =>
149→    route.fulfill({
150→      status: 200,
151→      contentType: "application/json",
152→      body: JSON.stringify(snap),
153→    }),
154→  );
155→  await page.route(`**/api/exercises/${EX_ID}/engine/context`, (route) =>
156→    route.fulfill({
157→      status: 200,
158→      contentType: "application/json",
159→      body: JSON.stringify(ctx),
160→    }),
161→  );
162→  await page.route("**/api/decisions*", async (route) => {
163→    if (route.request().url().includes("/engine/")) {
164→      await route.fallback();
165→      return;
166→    }
167→    await route.fulfill({
168→      status: 200,
169→      contentType: "application/json",
170→      body: JSON.stringify([]),
171→    });
172→  });
173→  await page.route(
174→    `**/api/exercises/${EX_ID}/engine/decisions`,
175→    async (route) => {
176→      if (route.request().method() === "GET") {
177→        await route.fulfill({
178→          status: 200,
179→          contentType: "application/json",
180→          body: JSON.stringify(decisions),
181→        });
182→      } else {
183→        await route.fallback();
184→      }
185→    },
186→  );
187→  await page.route("**/ws?*", (route) => route.abort("connectionrefused"));
