397→  private updateRole(
398→    exerciseId: number,
399→    participantId: string,
400→    role: string,
401→  ): MockParticipant | null {
402→    const list = this.rooms.get(exerciseId) ?? [];
403→    const p = list.find((x) => x.id === participantId);
404→    if (!p) return null;
405→    p.role = role;
406→    return p;
